WITH flattened AS (SELECT id, plan, val FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) li AS val) SELECT CASE WHEN val >= 71 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, SORT_ARRAY(COLLECT_SET(plan)) AS plan_list, SUM(val) FILTER (WHERE plan = 'starter') AS starter_total_val, ROUND(AVG(val), 2) AS avg_val FROM flattened GROUP BY CASE WHEN val >= 71 THEN 'LARGE' ELSE 'SMALL' END ORDER BY val_tier DESC NULLS LAST;
